// Runs in an n8n Code node. Read the uploaded binary through n8n's storage helper.
const upload = $input.first();
const keys = Object.keys(upload.binary || {});
if (keys.length !== 1) throw new Error('Upload one CSV or JSON file.');
const file = upload.binary[keys[0]];
const text = (await this.helpers.getBinaryDataBuffer(0, keys[0])).toString('utf8').replace(/^\uFEFF/, '');
let rows;
if (/\.json$/i.test(file.fileName || '')) {
  const parsed = JSON.parse(text);
  rows = Array.isArray(parsed) ? parsed : parsed.addresses;
  if (!Array.isArray(rows)) throw new Error('JSON must contain an array of address strings or objects with an address field.');
} else if (/\.csv$/i.test(file.fileName || '')) {
  // RFC-style CSV: quoted commas, escaped quotes, CRLF, and multiline fields.
  const table = [];
  let row = [], value = '', quoted = false, closed = false;
  const finishCell = () => { row.push(value); value = ''; closed = false; };
  const finishRow = () => { finishCell(); table.push(row); row = []; };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { value += '"'; i++; }
      else if (c === '"') { quoted = false; closed = true; }
      else value += c;
    } else if (c === ',') finishCell();
    else if (c === '\n' || c === '\r') { finishRow(); if (c === '\r' && text[i + 1] === '\n') i++; }
    else if (c === '"' && value === '' && !closed) quoted = true;
    else if (closed || c === '"') throw new Error('Malformed CSV quoting. Quote addresses containing commas.');
    else value += c;
  }
  if (quoted) throw new Error('CSV contains an unclosed quoted field.');
  if (value || row.length || closed) finishRow();
  const header = table.shift() || [];
  const columns = header.map(v => v.trim().toLowerCase());
  const addressColumn = columns.indexOf('address');
  if (addressColumn < 0 || columns.lastIndexOf('address') !== addressColumn) throw new Error('CSV needs exactly one address column.');
  rows = table.filter(r => r.some(v => v.trim())).map((r, i) => {
    if (r.length !== header.length) throw new Error('CSV row ' + (i + 2) + ' has the wrong number of columns.');
    return { address: r[addressColumn] };
  });
} else throw new Error('Choose a .csv or .json file.');

// Validate the whole upload before issuing requests. No fixed address-count cap.
const unique = new Map();
rows.forEach((row, index) => {
  const value = typeof row === 'string' ? row : row?.address;
  if (typeof value !== 'string' || !value.trim()) throw new Error('Missing address at input row ' + (index + 1) + '.');
  const address = value.trim();
  if (!unique.has(address)) unique.set(address, { json: { address, input_row: index + 1 }, pairedItem: { item: 0 } });
});
if (!unique.size) throw new Error('The file contains no addresses.');
return [...unique.values()];

return $input.all().map((item, i) => {
  const address = $('Extract addresses').itemMatching(i).json.address;
  const response = item.json;
  const code = Number(response.statusCode || 0);
  const body = response.body;
  const row = { input_row: $('Extract addresses').itemMatching(i).json.input_row, input_address: address, status: 'unexpected_response', http_status: code,
    match_review: '', zpid: '', returned_address: '', price: '', currency: '', bedrooms: '',
    bathrooms: '', living_area: '', home_type: '', home_status: '', zestimate: '', rent_zestimate: '' };
  if (code < 200 || code >= 300) row.status = (code === 429 || Number(body?.statusCode) === 429) ? 'rate_limited' : code ? 'http_error' : 'network_error';
  else if (body == null || (Array.isArray(body) && !body.length) ||
      (typeof body === 'object' && !Object.keys(body).length)) row.status = 'no_result';
  else if (Array.isArray(body)) row.status = body.length > 1 ? 'multiple_results_review' : 'unexpected_response';
  else if (body.zpid && body.address && typeof body.address === 'object') {
    row.status = 'returned'; row.match_review = 'required'; row.zpid = body.zpid;
    row.returned_address = ['streetAddress','city','state','zipcode'].map(k => body.address[k]).filter(Boolean).join(', ');
    const fields = {price:'price',currency:'currency',bedrooms:'bedrooms',bathrooms:'bathrooms',
      living_area:'livingArea',home_type:'homeType',home_status:'homeStatus',zestimate:'zestimate',rent_zestimate:'rentZestimate'};
    for (const [output, source] of Object.entries(fields)) row[output] = body[source] ?? '';
  }
  return {json:row, pairedItem:{item:i}};
});

const items = $input.all();
const columns = Object.keys(items[0].json);
const cell = value => {
  let text = String(value ?? '');
  // Keep spreadsheet applications from treating source strings as formulas.
  if (/^[\s]*[=+@-]/.test(text)) text = "'" + text;
  return '"' + text.replace(/"/g, '""') + '"';
};
const csv = [columns.map(cell).join(','), ...items.map(item => columns.map(k => cell(item.json[k])).join(','))].join('\r\n');
return [{json:{processed_addresses:items.length},binary:{data:await this.helpers.prepareBinaryData(Buffer.from(csv,'utf8'),'property-results.csv','text/csv')}}];
